pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: the residual after placing the item.
    let mut score = post_residual as f64;

    // Normalise ratios for later use
    let post_ratio = post_residual as f64 / bin_capacity as f64;
    let mean_ratio = mean_residual / bin_capacity as f64;
    let next_ratio = next_item_size as f64 / bin_capacity as f64;

    // 1. Penalise dead space aggressively
    score += 42.0 * post_ratio.powi(2);

    // 2. Penalise deviation from the mean residual
    score += 27.0 * ((post_ratio - mean_ratio).powi(2));

    // 3. Encourage bins that can immediately accommodate the next item
    if next_item_size <= post_residual {
        score -= 18.0;
    } else {
        let gap = (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        score += 14.0 * gap;
    }

    // 4. Progress‐based tolerance: early stages allow more waste
    let progress = step_index as f64 / total_items as f64;
    score += 6.0 * progress.powi(2);

    // 5. Penalise having too many open bins (quadratic to discourage large stacks)
    score += 1.2 * (open_bins_count as f64).powf(1.5);

    // 6. Reward a perfect fit when it is the only candidate
    if fitting_bins_count == 1 {
        score -= 28.0;
    } else if fitting_bins_count > 1 {
        // Slight penalty for many alternatives to keep us from wasting space
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // 7. Extra logic for opening a brand‑new empty bin
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Prefer opening a new bin only if it fills a decent fraction
        let new_bin_base = 22.0 - 33.0 * fill_ratio;
        score += new_bin_base.max(0.0);

        // Penalise when the remaining space after opening is far larger than average
        let residual_after = (bin_capacity - item_size) as f64;
        let excess = (residual_after / bin_capacity as f64 - mean_ratio).abs();
        let extra = 18.0 * excess * (1.0 - progress);
        score += extra;
    }

    // 8. Additional look‑ahead: if the next item is large relative to bin capacity
    //    and the current bin cannot hold it, discourage this bin more heavily.
    if next_ratio > 0.6 && post_ratio < next_ratio {
        score += 12.0 * (next_ratio - post_ratio);
    }

    // 9. Avoid bins with extremely low residual when next item is small
    if next_item_size < (bin_capacity / 8) && post_ratio < 0.1 {
        score += 8.0;
    }

    score
}

