pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score is the residual space left after placement.
    let mut score = post_residual as f64;

    // Ratios relative to capacity.
    let post_ratio = post_residual as f64 / bin_capacity as f64;
    let mean_ratio = mean_residual / bin_capacity as f64;
    let size_ratio = item_size as f64 / bin_capacity as f64;

    // Tight packing: reward bins that leave very little space.
    score -= 42.0 * (1.0 - post_ratio);

    // Prefer bins whose residual is close to the global mean residual.
    score -= 24.0 * (1.0 - (post_ratio - mean_ratio).abs());

    // Penalise variance from the mean residual more strongly.
    let diff = post_residual as f64 - mean_residual;
    score -= 7.0 * (diff * diff) / (bin_capacity as f64);

    // If many bins can accommodate the item, favour the one with the smallest residual.
    if fitting_bins_count > 6 {
        score -= 13.0 * post_ratio;
    }

    // Look‑ahead: if the next item cannot fit, penalise; otherwise reward.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // Cannot fit next item – penalty scaled by how far we are from the end.
            let large_next = next_item_size as f64 / bin_capacity as f64;
            score += 5.0 * (next_item_size - post_residual) as f64 * (1.0 + large_next);
        } else {
            // Fits comfortably – slight reward.
            score -= 2.5 * (post_residual - next_item_size) as f64;
        }
    }

    // Progress penalty: as we near the end we become more conservative.
    let progress = step_index as f64 / total_items as f64;
    score += 6.0 * progress;

    // Open‑bins penalty – grows quadratically.
    score += 1.6 * (open_bins_count as f64).powi(2) / (total_items as f64).max(1.0);

    // Special handling for a brand‑new empty bin candidate.
    if bin_residual == bin_capacity {
        // New‑bin penalty inversely proportional to how large the item is.
        let new_bin_penalty = 18.0 * (1.0 - size_ratio).max(0.0);
        // Reduce the penalty as we approach the end of the stream.
        let late_factor = 1.0 - progress;
        score += new_bin_penalty * late_factor;

        // Reward the residual left in a fresh bin, scaled by the fraction of the stream remaining.
        score += (post_residual as f64 / bin_capacity as f64) * (1.0 - progress) * 2.8;
    }

    // Extra reward for a perfect fit after placement.
    if post_residual == 0 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let post_ratio = post_f / cap_f;
    let mean_ratio = mean_residual / cap_f;

    // Base score: prefer lower waste
    let mut score = post_f;

    // Deviation from mean residual penalty
    let diff = (post_ratio - mean_ratio).abs();
    score -= 22.0 * diff;

    // Strong non‑linear waste penalty
    score -= 48.0 * post_ratio.powf(1.25);

    // Fitting bins count influence
    if fitting_bins_count > 1 {
        if post_ratio < mean_ratio {
            score -= 9.0; // bonus for reducing waste below mean
        } else {
            score += 4.0; // slight penalty if waste still high
        }
    } else if fitting_bins_count == 1 {
        if post_ratio > mean_ratio {
            score += 12.0; // only fit but waste high
        }
    }

    // Lookahead: penalize if next item cannot fit after this placement
    if next_item_size > post_residual {
        let diff_next = (next_item_size - post_residual) as f64;
        score += 6.5 * diff_next;
    }

    // Progress weighting: towards end, prefer using existing bins
    let progress = step_index as f64 / total_items as f64;
    score += 9.0 * progress;

    // Open bins penalty: discourage too many open bins
    score += 0.65 * open_bins_count as f64;

    // New bin candidate handling
    if bin_residual == bin_capacity {
        let new_waste = (bin_capacity - item_size) as f64;
        let waste_ratio = new_waste / cap_f;
        let penalty = 17.0 - 11.0 * (item_size as f64 / bin_capacity as f64);
        score += penalty.max(0.0);
        // Additional penalty for being late in the stream
        score += waste_ratio * (1.0 - progress);
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let capacity_f = bin_capacity as f64;
    let post_residual_f = post_residual as f64;
    let mean_ratio = mean_residual / capacity_f;
    let post_ratio = post_residual_f / capacity_f;

    // 1. Basic residual penalty – lower residual is better
    let mut score = 10.0 * post_ratio;

    // 2. Reward closeness to the mean residual
    score -= 15.0 * (1.0 - (post_ratio - mean_ratio).abs());

    // 3. Penalise variance from the mean
    let diff = post_residual_f - mean_residual;
    score -= 8.0 * (diff * diff) / capacity_f;

    // 4. Look‑ahead handling
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits – discourage excessive slack
            let slack = (post_residual - next_item_size) as f64;
            score += 2.0 * (slack * slack) / capacity_f;
        } else {
            // Next item does not fit – penalise this bin heavily
            score += 5.0 * (next_item_size - post_residual) as f64;
        }
    }

    // 5. Progress‑dependent penalty – become stricter as we finish
    let progress = step_index as f64 / total_items as f64;
    score += 5.0 * progress;

    // 6. Open‑bins penalty – quadratic growth
    score += 0.6 * (open_bins_count as f64).powi(2) / total_items.max(1) as f64;

    // 7. Fit‑count adjustment – if many bins can fit, prefer tighter fits
    if fitting_bins_count > 5 {
        score += 8.0 * post_ratio;
    }

    // 8. New‑bin candidate handling
    if bin_residual == bin_capacity {
        let size_ratio = item_size as f64 / capacity_f;
        let new_bin_base = 12.0 * (1.0 - size_ratio).max(0.0);
        // Reduce penalty near the end
        score += new_bin_base * (1.0 - progress);
        // Reward residual left after opening a fresh bin
        score -= post_ratio * (1.0 - progress) * 1.2;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Basic residual ratio
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    // Start with the raw residual as the baseline score
    let mut score = post_residual as f64;

    // 1. Penalise large residuals proportionally to capacity
    score += 20.0 * residual_ratio;

    // 2. Reward tight packing – smaller residual gives lower score
    score -= 15.0 * (1.0 - residual_ratio);

    // 3. Reward closeness to the mean residual
    let diff_mean = (post_residual as f64 - mean_residual).abs();
    score -= 10.0 * (1.0 - diff_mean / bin_capacity as f64);

    // 4. Penalise high variance from the mean
    let variance = (post_residual as f64 - mean_residual).powi(2);
    score -= 5.0 * variance / bin_capacity as f64;

    // 5. When many bins can fit, favour the one with the smallest residual
    if fitting_bins_count > 4 {
        score -= 6.0 * (1.0 - residual_ratio);
    }

    // 6. Look‑ahead penalty: avoid leaving space smaller than the next item
    if next_item_size > post_residual {
        score += 3.0 * (next_item_size - post_residual) as f64;
    }

    // 7. Penalise tight bins when the next item is large relative to capacity
    if (next_item_size as f64 / bin_capacity as f64) > 0.6 {
        score += 2.0 * (1.0 - residual_ratio);
    }

    // 8. Reward residuals that are close to the next item size
    let residual_to_next = (post_residual as i32 - next_item_size as i32).abs() as f64;
    score -= 10.0 * (-residual_to_next / bin_capacity as f64).exp();

    // 9. Progress penalty – become more conservative toward the end of the stream
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += 2.0 * (progress - 0.8);
    }

    // 10. Penalise having many open bins to encourage closing
    score += 0.8 * open_bins_count as f64;

    // 11. New‑bin handling
    if bin_residual == bin_capacity {
        let ratio = item_size as f64 / bin_capacity as f64;
        let new_bin_penalty = if ratio > 0.7 {
            3.0
        } else {
            7.0 * (1.0 - ratio)
        };
        score += new_bin_penalty;
        // Adjust for the residual left after placing the item in a new bin,
        // scaled by the remaining progress.
        score += 1.5 * residual_ratio * (1.0 - progress);
    }

    score
}
